import{_ as a,c as e,o,a0 as i}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively.","frontmatter":{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively."},"headers":[],"relativePath":"es/blog/team-communication.md","filePath":"es/blog/team-communication.md"}');const l=a({name:"es/blog/team-communication.md"},[["render",function(a,n,l,r,t,s){return o(),e("div",null,[...n[0]||(n[0]=[i('<h1 id="comunicacion-bajo-presion" tabindex="-1">Comunicación bajo presión <a class="header-anchor" href="#comunicacion-bajo-presion" aria-label="Permalink to &quot;Comunicación bajo presión&quot;">​</a></h1><p>En la petanca, la comunicación puede hacer o deshacer un equipo. Las palabras adecuadas en el momento oportuno generan confianza y claridad. Las palabras equivocadas, o el silencio cuando se necesitan palabras, pueden desmantelar incluso a equipos hábiles.</p><h2 id="por-que-es-importante-la-comunicacion" tabindex="-1">Por qué es importante la comunicación <a class="header-anchor" href="#por-que-es-importante-la-comunicacion" aria-label="Permalink to &quot;Por qué es importante la comunicación&quot;">​</a></h2><p>Los equipos de petanca se enfrentan a desafíos de comunicación únicos:</p><ul><li>Las decisiones deben tomarse rápidamente</li><li>La presión afecta cómo hablamos y escuchamos</li><li>Las señales no verbales son visibles para los oponentes.</li><li>El rendimiento individual afecta la dinámica del equipo</li></ul><p>La comunicación eficaz crea:</p><ul><li>Comprensión compartida de la estrategia</li><li>Apoyo mutuo y confianza</li><li>Toma de decisiones rápida y clara</li><li>Resiliencia en momentos difíciles</li></ul><h2 id="los-principios-de-la-comunicacion" tabindex="-1">Los principios de la comunicación <a class="header-anchor" href="#los-principios-de-la-comunicacion" aria-label="Permalink to &quot;Los principios de la comunicación&quot;">​</a></h2><h3 id="_1-claridad-antes-que-cantidad" tabindex="-1">1. Claridad antes que cantidad <a class="header-anchor" href="#_1-claridad-antes-que-cantidad" aria-label="Permalink to &quot;1. Claridad antes que cantidad&quot;">​</a></h3><p>Bajo presión, menos es más. Una comunicación clara y concisa es mejor que largas discusiones.</p><p><strong>En lugar de:</strong> &quot;Creo que tal vez deberíamos intentar señalar aquí, pero no estoy seguro, ¿qué opinas? El terreno parece complicado...&quot;</p><p><strong>Di:</strong> &quot;Señalaré el lado izquierdo. El terreno está mejor allí&quot;.</p><h3 id="_2-encuadre-positivo" tabindex="-1">2. Encuadre positivo <a class="header-anchor" href="#_2-encuadre-positivo" aria-label="Permalink to &quot;2. Encuadre positivo&quot;">​</a></h3><p>Enmarcar las comunicaciones de forma constructiva:</p><p><strong>En lugar de:</strong> &quot;No te lo pierdas&quot; <strong>Di:</strong> &quot;Lo tienes todo bajo control, confía en tu lanzamiento&quot;</p><p><strong>En lugar de:</strong> &quot;Eso fue terrible&quot; <strong>Di:</strong> &quot;Sacúdetelo, siguiente&quot;</p><h3 id="_3-enfoque-actual" tabindex="-1">3. Enfoque actual <a class="header-anchor" href="#_3-enfoque-actual" aria-label="Permalink to &quot;3. Enfoque actual&quot;">​</a></h3><p>Mantenga la comunicación centrada en lo que sigue, no en lo que ya pasó:</p><p><strong>En lugar de:</strong> &quot;¿Por qué lo tiraste ahí?&quot; <strong>Di:</strong> &quot;Bien, ¿cuál es nuestra mejor opción ahora?&quot;</p><h3 id="_4-lenguaje-de-propiedad" tabindex="-1">4. Lenguaje de propiedad <a class="header-anchor" href="#_4-lenguaje-de-propiedad" aria-label="Permalink to &quot;4. Lenguaje de propiedad&quot;">​</a></h3><p>Utilice declaraciones en &quot;yo&quot; para sus propias acciones, y en &quot;nosotros&quot; para situaciones de equipo:</p><ul><li>&quot;Tomaré esta foto&quot;</li><li>&quot;Necesitamos proteger el punto&quot;</li><li>&quot;Creo que deberíamos...&quot;</li></ul><h2 id="que-comunicar" tabindex="-1">Qué comunicar <a class="header-anchor" href="#que-comunicar" aria-label="Permalink to &quot;Qué comunicar&quot;">​</a></h2><h3 id="antes-de-cada-fin" tabindex="-1">Antes de cada fin <a class="header-anchor" href="#antes-de-cada-fin" aria-label="Permalink to &quot;Antes de cada fin&quot;">​</a></h3><ul><li><strong>Discusión de estrategia</strong>: Breve alineación sobre el enfoque</li><li><strong>Claridad de roles</strong>: Quién hace qué</li><li><strong>Observaciones del terreno</strong>: Condiciones relevantes</li></ul><h3 id="durante-el-juego" tabindex="-1">Durante el juego <a class="header-anchor" href="#durante-el-juego" aria-label="Permalink to &quot;Durante el juego&quot;">​</a></h3><ul><li><strong>Decisiones</strong>: Declaración clara de la acción prevista</li><li><strong>Apoyo</strong>: Ánimo antes de los lanzamientos</li><li><strong>Información</strong>: Observaciones relevantes sobre el terreno o los oponentes.</li></ul><h3 id="despues-de-los-lanzamientos" tabindex="-1">Después de los lanzamientos <a class="header-anchor" href="#despues-de-los-lanzamientos" aria-label="Permalink to &quot;Después de los lanzamientos&quot;">​</a></h3><ul><li><strong>Agradecimiento</strong>: Breve reconocimiento (bueno o malo)</li><li><strong>Ajuste</strong>: Cualquier cambio estratégico necesario</li><li><strong>Restablecer</strong>: Ayuda a tu compañero de equipo a reenfocarse</li></ul><h2 id="que-no-comunicar" tabindex="-1">Qué NO comunicar <a class="header-anchor" href="#que-no-comunicar" aria-label="Permalink to &quot;Qué NO comunicar&quot;">​</a></h2><h3 id="evitar-durante-momentos-de-presion" tabindex="-1">Evitar durante momentos de presión <a class="header-anchor" href="#evitar-durante-momentos-de-presion" aria-label="Permalink to &quot;Evitar durante momentos de presión&quot;">​</a></h3><ul><li>Instrucciones técnicas (&quot;Mantenga el codo hacia adentro&quot;)</li><li>Crítica de los lanzamientos pasados</li><li>Expresiones de frustración</li><li>Duda sobre la capacidad del compañero de equipo</li><li>Análisis excesivo</li></ul><h3 id="evitar-en-general" tabindex="-1">Evitar en general <a class="header-anchor" href="#evitar-en-general" aria-label="Permalink to &quot;Evitar en general&quot;">​</a></h3><ul><li>Lenguaje de culpa</li><li>Sarcasmo o agresión pasiva</li><li>Comparaciones con otros jugadores</li><li>Predicciones de fracaso</li></ul><h2 id="comunicacion-no-verbal" tabindex="-1">Comunicación no verbal <a class="header-anchor" href="#comunicacion-no-verbal" aria-label="Permalink to &quot;Comunicación no verbal&quot;">​</a></h2><p>Tu lenguaje corporal habla fuerte:</p><h3 id="senales-positivas" tabindex="-1">Señales positivas <a class="header-anchor" href="#senales-positivas" aria-label="Permalink to &quot;Señales positivas&quot;">​</a></h3><ul><li>Contacto visual con compañeros de equipo</li><li>Postura abierta y relajada</li><li>Asentir y reconocer</li><li>Movimientos tranquilos y constantes</li></ul><h3 id="senales-negativas-evitar" tabindex="-1">Señales negativas (Evitar) <a class="header-anchor" href="#senales-negativas-evitar" aria-label="Permalink to &quot;Señales negativas (Evitar)&quot;">​</a></h3><ul><li>Poner los ojos en blanco o suspirar</li><li>Alejándose de sus compañeros de equipo</li><li>Brazos cruzados o postura cerrada</li><li>Frustración visible</li></ul><h3 id="companeros-de-equipo-de-lectura" tabindex="-1">Compañeros de equipo de lectura <a class="header-anchor" href="#companeros-de-equipo-de-lectura" aria-label="Permalink to &quot;Compañeros de equipo de lectura&quot;">​</a></h3><p>Aprenda a reconocer cuándo los compañeros de equipo necesitan:</p><ul><li><strong>Espacio</strong>: Están procesando, no interrumpas</li><li><strong>Apoyo</strong>: Están luchando, ofréceles ánimo.</li><li><strong>Información</strong>: Son inciertas, aportan claridad</li><li><strong>Energía</strong>: Son planos, aportan entusiasmo.</li></ul><h2 id="roles-de-comunicacion" tabindex="-1">Roles de comunicación <a class="header-anchor" href="#roles-de-comunicacion" aria-label="Permalink to &quot;Roles de comunicación&quot;">​</a></h2><h3 id="el-puntero" tabindex="-1">El puntero <a class="header-anchor" href="#el-puntero" aria-label="Permalink to &quot;El puntero&quot;">​</a></h3><ul><li>Comunica tu lectura del terreno</li><li>Indique claramente su ubicación prevista</li><li>Pida sugerencias cuando no esté seguro</li></ul><h3 id="el-tirador" tabindex="-1">El tirador <a class="header-anchor" href="#el-tirador" aria-label="Permalink to &quot;El tirador&quot;">​</a></h3><ul><li>Confirmar selección de objetivo</li><li>Comunicar el nivel de confianza</li><li>Solicitar información sobre ángulos</li></ul><h3 id="el-medio-capitan" tabindex="-1">El Medio/Capitán <a class="header-anchor" href="#el-medio-capitan" aria-label="Permalink to &quot;El Medio/Capitán&quot;">​</a></h3><ul><li>Facilitar las discusiones en equipo</li><li>Tomar decisiones finales cuando sea necesario</li><li>Gestionar la energía y el enfoque del equipo</li></ul><h2 id="situaciones-de-presion" tabindex="-1">Situaciones de presión <a class="header-anchor" href="#situaciones-de-presion" aria-label="Permalink to &quot;Situaciones de presión&quot;">​</a></h2><h3 id="cuando-detras" tabindex="-1">Cuando detrás <a class="header-anchor" href="#cuando-detras" aria-label="Permalink to &quot;Cuando detrás&quot;">​</a></h3><ul><li>Manténgase centrado en la solución</li><li>Mantener la energía positiva</li><li>Evite la culpa o la frustración</li><li>Celebra los pequeños triunfos</li></ul><h3 id="cuando-adelante" tabindex="-1">Cuando adelante <a class="header-anchor" href="#cuando-adelante" aria-label="Permalink to &quot;Cuando adelante&quot;">​</a></h3><ul><li>Manténgase concentrado, evite la complacencia</li><li>Mantenga la comunicación consistente</li><li>No cambies lo que funciona</li></ul><h3 id="punto-de-partido-de-ellos" tabindex="-1">Punto de partido (de ellos) <a class="header-anchor" href="#punto-de-partido-de-ellos" aria-label="Permalink to &quot;Punto de partido (de ellos)&quot;">​</a></h3><ul><li>Reconozca la presión brevemente</li><li>Centrarse en el proceso</li><li>Apoyarnos mutuamente de forma visible</li></ul><h3 id="punto-de-partido-el-nuestro" tabindex="-1">Punto de partido (el nuestro) <a class="header-anchor" href="#punto-de-partido-el-nuestro" aria-label="Permalink to &quot;Punto de partido (el nuestro)&quot;">​</a></h3><ul><li>Mantén la calma y la concentración</li><li>Evite las celebraciones prematuras</li><li>Ejecutar normalmente</li></ul><h2 id="desarrollar-habilidades-de-comunicacion" tabindex="-1">Desarrollar habilidades de comunicación <a class="header-anchor" href="#desarrollar-habilidades-de-comunicacion" aria-label="Permalink to &quot;Desarrollar habilidades de comunicación&quot;">​</a></h2><h3 id="en-la-practica" tabindex="-1">En la práctica <a class="header-anchor" href="#en-la-practica" aria-label="Permalink to &quot;En la práctica&quot;">​</a></h3><ul><li>Practique la comunicación durante el entrenamiento</li><li>Dar y recibir retroalimentación sobre la comunicación.</li><li>Experimente con diferentes enfoques</li></ul><h3 id="acuerdos-de-equipo" tabindex="-1">Acuerdos de equipo <a class="header-anchor" href="#acuerdos-de-equipo" aria-label="Permalink to &quot;Acuerdos de equipo&quot;">​</a></h3><p>Establecer normas de equipo:</p><ul><li>Cómo manejamos los desacuerdos</li><li>¿Cómo se ve el soporte?</li><li>Cuándo hablar y cuándo callar</li></ul><h3 id="analisis-posterior-al-partido" tabindex="-1">Análisis posterior al partido <a class="header-anchor" href="#analisis-posterior-al-partido" aria-label="Permalink to &quot;Análisis posterior al partido&quot;">​</a></h3><p>Discutir la comunicación:</p><ul><li>¿Qué funcionó bien?</li><li>¿Qué podría mejorar?</li><li>¿Hay algún malentendido que deba abordarse?</li></ul><h2 id="cuando-la-comunicacion-falla" tabindex="-1">Cuando la comunicación falla <a class="header-anchor" href="#cuando-la-comunicacion-falla" aria-label="Permalink to &quot;Cuando la comunicación falla&quot;">​</a></h2><h3 id="en-el-momento" tabindex="-1">En el momento <a class="header-anchor" href="#en-el-momento" aria-label="Permalink to &quot;En el momento&quot;">​</a></h3><ol><li>Toma un respiro</li><li>Reinicia con una simple declaración: &quot;Concentrémonos en este lanzamiento&quot;.</li><li>Regreso a lo básico: claro, positivo, presente</li></ol><h3 id="despues-del-partido" tabindex="-1">Después del partido <a class="header-anchor" href="#despues-del-partido" aria-label="Permalink to &quot;Después del partido&quot;">​</a></h3><ul><li>Abordar los problemas con calma</li><li>Centrarse en los comportamientos, no en las personalidades</li><li>Acordar mejoras</li><li>Avanzar juntos</li></ul><h2 id="el-apoyo-silencioso" tabindex="-1">El apoyo silencioso <a class="header-anchor" href="#el-apoyo-silencioso" aria-label="Permalink to &quot;El apoyo silencioso&quot;">​</a></h2><p>A veces la mejor comunicación es la presencia:</p><ul><li>De pie junto a un compañero de equipo con dificultades</li><li>Una mano en el hombro</li><li>Un gesto de confianza</li><li>Simplemente estar ahí</li></ul><p>Las palabras no siempre son necesarias. La conexión sí.</p><hr><p>| <em>Relacionado: <a href="/es/educacion/jugador-de-equipo/">Dinámica de equipo</a> | <a href="/es/educación/jugador-de-equipo/comunicación">Comunicación</a> | <a href="/es/educacion/fuerza-mental/manejo-de-la-presion">Manejo de la presión</a></em> |</p>',79)])])}]]);export{n as __pageData,l as default};
